public static String unescapeJava(String str) throws Exception {
    if (str == null) return null;
    StringBuilder sb = new StringBuilder(str.length());
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\' && i + 1 < str.length()) {
            char next = str.charAt(i + 1);
            switch (next) {
                case 'b':
                    sb.append('\b');
                    i++;
                    break;
                case 't':
                    sb.append('\t');
                    i++;
                    break;
                case 'n':
                    sb.append('\n');
                    i++;
                    break;
                case 'f':
                    sb.append('\f');
                    i++;
                    break;
                case 'r':
                    sb.append('\r');
                    i++;
                    break;
                case '\"':
                    sb.append('\"');
                    i++;
                    break;
                case '\'':
                    sb.append('\'');
                    i++;
                    break;
                case '\\':
                    sb.append('\\');
                    i++;
                    break;
                case 'u':
                    if (i + 5 < str.length()) {
                        String hex = str.substring(i + 2, i + 6);
                        try {
                            int code = Integer.parseInt(hex, 16);
                            sb.append((char) code);
                            i += 5;
                        } catch (NumberFormatException e) {
                            sb.append('\\').append('u');
                            i++;
                        }
                    } else {
                        sb.append('\\').append('u');
                        i++;
                    }
                    break;
                default:
                    if (next >= '0' && next <= '7') {
                        int j = i + 1;
                        int val = next - '0';
                        int count = 1;
                        while (j + 1 < str.length() && count < 3) {
                            char d = str.charAt(j + 1);
                            if (d >= '0' && d <= '7') {
                                val = val * 8 + (d - '0');
                                j++;
                                count++;
                            } else {
                                break;
                            }
                        }
                        sb.append((char) val);
                        i = j;
                    } else {
                        sb.append(next);
                        i++;
                    }
                    break;
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

