protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || tour.isEmpty()) return null;
    // Build maps from source to edge and target to edge
    Map<V, E> outEdgeMap = new HashMap<>();
    Map<V, E> inEdgeMap = new HashMap<>();
    for (E e : tour) {
        V src = graph.getEdgeSource(e);
        V tgt = graph.getEdgeTarget(e);
        outEdgeMap.put(src, e);
        inEdgeMap.put(tgt, e);
    }
    // Find a start vertex (a vertex that is not a target of any edge)
    V start = null;
    for (V v : outEdgeMap.keySet()) {
        if (!inEdgeMap.containsKey(v)) {
            start = v;
            break;
        }
    }
    // If no such vertex (cycle), pick any source
    if (start == null) {
        start = graph.getEdgeSource(tour.iterator().next());
    }
    List<E> edgeList = new ArrayList<>();
    List<V> vertexList = new ArrayList<>();
    V current = start;
    vertexList.add(current);
    while (edgeList.size() < tour.size()) {
        E e = outEdgeMap.get(current);
        if (e == null) break;
        edgeList.add(e);
        V next = graph.getEdgeTarget(e);
        vertexList.add(next);
        current = next;
    }
    double weight = 0.0;
    for (E e : edgeList) {
        weight += graph.getEdgeWeight(e);
    }
    return new GraphPathImpl<>(graph, start, current, edgeList, weight);
}

