public static String applyRelativePath(String path, String relativePath) {
    // Split the base path into components, ignoring empty parts
    String[] pathParts = path.split("/");
    java.util.List<String> stack = new java.util.ArrayList<>();
    for (String part : pathParts) {
        if (!part.isEmpty()) {
            stack.add(part);
        }
    }

    // Process each component of the relative path
    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            // No-op for empty or current directory
            continue;
        } else if (part.equals("..")) {
            // Move up one directory if possible
            if (!stack.isEmpty()) {
                stack.remove(stack.size() - 1);
            }
        } else {
            // Normal directory/file component
            stack.add(part);
        }
    }

    // Reconstruct the resulting path
    StringBuilder result = new StringBuilder();
    if (path.startsWith("/")) {
        result.append("/");
    }
    for (int i = 0; i < stack.size(); i++) {
        if (i > 0) {
            result.append("/");
        }
        result.append(stack.get(i));
    }

    return result.toString();
}

